import{_ as t,C as s,o as i,c as o,ag as r,E as n}from"./chunks/framework.DUTPmUpA.js";const l="/_assets/xsQnBg9.D1ctVgfV.png",p="/_assets/HrXehTo.D9Zq927X.png",c="/_assets/nKUPQQG.DikSMRUS.png",d="/_assets/j4T6CW8.plXavxga.png",m="/_assets/FkcOxgM.BdMA3loi.png",_="/_assets/qQyXGI9.BstvriyV.png",g="/_assets/xCQSs0C.D8gYfk4w.png",h="/_assets/AQT6Foz.CF532ivC.png",u="/_assets/JpsmJxS.5OK4MtL4.png",v="/_assets/AmpleNaiveKiwi.Dlv4dvsh.mp4",C=JSON.parse('{"title":"Извлечение и компиляция файлов VTEX","description":"","frontmatter":{"title":"Извлечение и компиляция файлов VTEX","author":"HMFD","steamId":"76561198053730418","date":"21.01.2015"},"headers":[],"relativePath":"assets/extracting-and-compiling-vtex-files.md","filePath":"assets/extracting-and-compiling-vtex-files.md"}'),b={name:"assets/extracting-and-compiling-vtex-files.md"};function x(T,e,f,V,k,X){const a=s("StaticVideo");return i(),o("div",null,[e[0]||(e[0]=r('<h1 id="извлечение-и-компиляция-фаилов-vtex" tabindex="-1">Извлечение и компиляция файлов VTEX <a class="header-anchor" href="#извлечение-и-компиляция-фаилов-vtex" aria-label="Permalink to &quot;Извлечение и компиляция файлов VTEX&quot;">​</a></h1><p>Привет всем. Недавно я просматривал файлы <code>.VTEX</code>, используемые большинством спрайтов и эффектов частиц в игре, но не смог найти по ним никакой подробной документации. Поэтому я решил написать это небольшое руководство, на случай, если оно кому-нибудь еще окажется полезным.</p><h2 id="извлечение-из-vtex" tabindex="-1">Извлечение из VTEX <a class="header-anchor" href="#извлечение-из-vtex" aria-label="Permalink to &quot;Извлечение из VTEX&quot;">​</a></h2><ol><li>Извлечь изображения из скомпилированных файлов VTEX (<code>.VTEX_C</code>) на самом деле довольно просто, но сначала нам нужны эти файлы. Если вы еще не распаковали их, вы можете найти их в <code>pak01_dir.vpk</code>, который находится в вашей папке dota_ugc\\game\\dota_imported. Используйте такой инструмент, как GCFScape или <a href="https://s2v.app/" target="_blank" rel="noreferrer">Source 2 Viewer</a>, чтобы открыть и извлечь нужные файлы.</li></ol><p><img src="'+l+'" alt="img"></p><ol start="2"><li>Затем перейдите в каталог dota_ugc\\game\\bin\\win64 (по какой-то причине инструменты отсутствуют в каталоге win32). Введите следующее:</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resourceinfo.exe -i &lt;your vtex_c file&gt; -debug tga -mip</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>При этом извлекаются различные MIP-карты и сохраняются как отдельные изображения TGA. Если все пройдет хорошо, у вас должно получиться что-то вроде этого:</p><p><img src="'+p+'" alt="img"></p><p>Кроме того, у вас также должно быть одно или несколько изображений TGA в вашем каталоге win64, в зависимости от того, сколько уровней MIP имеет текстура. Откройте образ с <code>_mip0</code>, так как это базовый (исходный) образ.</p><p><img src="'+c+'" alt="img"></p><ol start="3"><li>Шага нет. 3. Поздравляем. Вы успешно извлекли базовое изображение TGA из скомпилированного файла VTEX. Легко, правда?</li></ol><h2 id="компиляция-в-vtex" tabindex="-1">Компиляция в VTEX <a class="header-anchor" href="#компиляция-в-vtex" aria-label="Permalink to &quot;Компиляция в VTEX&quot;">​</a></h2><ol><li>Компиляция в VTEX также довольно проста. Сначала поместите все изображения TGA, которые вы планируете использовать, в один каталог. Если вы компилируете только один образ, то это не проблема. Однако в этом примере я изменю несколько значков в исходном файле msg_01.vtex.</li></ol><p><img src="'+d+'" alt="img"></p><ol start="2"><li>Далее нам нужно создать файл VTEX. Файлы VTEX представляют собой файлы данных ASCII, которые описывают свойства текстуры, входные и выходные данные. Если вы создали свой мод на основе пустого шаблона, вы должны найти несколько примеров файлов VTEX в каталоге dota_ugc\\content\\dota_addons\\(modname)\\materials\\particle. Откройте один из них, и он должен выглядеть примерно так:</li></ol><p><img src="'+m+'" alt="img"></p><p>Просто замените имя файла в выделенной строке («m_fileName» в разделе «CDmeInputTexture») именем вашего изображения TGA, и все готово. 2b) Однако если вы создаете текстуру с последовательностями, сначала необходимо создать файл <code>.MKS</code>. Как и файлы VTEX, файлы <code>.MKS</code> представляют собой файлы данных ASCII, хотя эти файлы описывают, как и какие спрайты отображать в игре. Обратитесь к <a href="https://developer.valvesoftware.com/wiki/Animated_Particles" target="_blank" rel="noreferrer">Valve Developer Wiki</a> для получения дополнительной информации о файлах MKS и анимированных частицах в целом. Обратите внимание, что вам НЕ нужно сначала компилировать файлы MKS с помощью <code>mksheet.exe</code>.</p><p>Получив файл <code>.mks</code>, замените имя файла, как указано выше, на имя файла MKS.</p><ol start="3"><li>Вернитесь в dota_ugc\\game\\bin\\win64 и введите следующее:</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resourcecompiler -i &lt;your vtex file&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Если все пойдет хорошо, вы должны увидеть что-то вроде этого:</p><p><img src="'+_+'" alt="img"></p><p>Вы также должны увидеть файл <code>.VTEX_C</code> где-то в папке <code>dota_ugc\\game\\dota_addons\\(modname)\\materials</code>, который теперь вы можете свободно использовать в своем моде.</p><p><img src="'+g+'" alt="img"></p><h2 id="скачать" tabindex="-1">Скачать <a class="header-anchor" href="#скачать" aria-label="Permalink to &quot;Скачать&quot;">​</a></h2><p>Если вы хотите использовать пример файла <code>.VTEX_C</code>, созданный в этом руководстве, для использования в своем моде, вы можете скачать его <a href="https://www.mediafire.com/download/fgce2192os392on/iw_msg_01.zip" target="_blank" rel="noreferrer">here</a>. Для сравнения:</p><p><img src="'+h+'" alt="img"> <img src="'+u+'" alt="img"></p><h2 id="бонусная-гифка" tabindex="-1">Бонусная гифка <a class="header-anchor" href="#бонусная-гифка" aria-label="Permalink to &quot;Бонусная гифка&quot;">​</a></h2>',29)),n(a,{path:v})])}const S=t(b,[["render",x]]);export{C as __pageData,S as default};
